// === Tab: mySketch ===
// ============================================================
// MERCURY
// Interactive Particle Planet + Cosmic Sound
// Based on the original 8000-particle system
// ============================================================

let isMobile = /iPhone|iPod|Android/i.test(navigator.userAgent);

let repel_radius;
let radius_;
let angle = 0;

let points = [];

const particles = 8000;

// Particle physics
const attraction = 0.01;
const damping = 0.9;
const repel_strength = 28;


// ============================================================
// AUDIO VARIABLES
// ============================================================

let audioCtx = null;
let masterGain = null;

let padGain = null;
let padFilter = null;

let audioStarted = false;

let lastCrystalTime = 0;


// ============================================================
// SETUP
// ============================================================

function setup() {

	describe(
		"An interactive particle representation of Mercury. " +
		"The particles scatter when touched by the mouse " +
		"and slowly return to their original positions."
	);


	// --------------------------------------------------------
	// Canvas
	// --------------------------------------------------------

	if (isMobile) {

		createCanvas(360, 360);

		radius_ = 160;
		repel_radius = 60;

	} else {

		createCanvas(900, 700);

		radius_ = 250;
		repel_radius = 90;
	}


	pixelDensity(1);


	// --------------------------------------------------------
	// Create particles
	// --------------------------------------------------------

	for (let i = 0; i < particles; i++) {

		points.push({

			index: i,

			pos: createVector(0, 0),

			vel: createVector(0, 0)

		});
	}


	// --------------------------------------------------------
	// Original particle formation
	// --------------------------------------------------------

	angle = 0;

	updateTargets();


	for (let p of points) {

		p.vel.set(0, 0);
	}
}


// ============================================================
// DRAW
// ============================================================

function draw() {

	background(0);


	// --------------------------------------------------------
	// Move to center
	// --------------------------------------------------------

	translate(
		width / 2,
		height / 2
	);


	// ========================================================
	// MERCURY RING
	// ========================================================

	noFill();

	let ringPulse =
		1 +
		sin(frameCount * 0.015) *
		0.015;


	// outer atmospheric ring

	stroke(
		80,
		180,
		255,
		38
	);

	strokeWeight(2);

	ellipse(
		0,
		0,
		radius_ * 2.18 * ringPulse,
		radius_ * 2.18 * ringPulse
	);


	// inner, even softer ring

	stroke(
		120,
		210,
		255,
		18
	);

	ellipse(
		0,
		0,
		radius_ * 2.08 * ringPulse,
		radius_ * 2.08 * ringPulse
	);


	// ========================================================
	// MOUSE POSITION
	// ========================================================

	let mouse = createVector(
		(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2,
		(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2
	);


	// ========================================================
	// PARTICLES
	// ========================================================

	for (let p of points) {

		let i = p.index;


		// ----------------------------------------------------
		// Original rotating "home" position
		// ----------------------------------------------------

		let homeX =
			sin(i + angle) *
			sin(i * i) *
			radius_;


		let homeY =
			cos(i * i) *
			radius_;


		let home =
			createVector(
				homeX,
				homeY
			);


		// ----------------------------------------------------
		// Spring force
		// Particles always try to return home
		// ----------------------------------------------------

		let toHome =
			p5.Vector.sub(
				home,
				p.pos
			);


		let spring =
			toHome.mult(attraction);


		p.vel.add(spring);


		// ----------------------------------------------------
		// Mouse repulsion
		// ----------------------------------------------------

		let awayFromMouse =
			p5.Vector.sub(
				p.pos,
				mouse
			);


		let mouseDistSq =
			awayFromMouse.magSq();


		if (
			mouseDistSq > 0.1 &&
			mouseDistSq <
			repel_radius * repel_radius
		) {

			let mouseDistance =
				sqrt(mouseDistSq);


			awayFromMouse.normalize();


			// Natural falloff
			let repel =
				repel_strength *
				(
					1 -
					mouseDistance /
					repel_radius
				);


			awayFromMouse.mult(repel);


			p.vel.add(
				awayFromMouse
			);
		}


		// ----------------------------------------------------
		// Damping
		// ----------------------------------------------------

		p.vel.mult(damping);


		// ----------------------------------------------------
		// Move
		// ----------------------------------------------------

		p.pos.add(p.vel);


		// ----------------------------------------------------
		// Particle appearance
		// ----------------------------------------------------

		// Very subtle blue-white Mercury color

		let blueVariation =
			15 +
			sin(i * 0.013) * 12;


		stroke(
			175 + blueVariation * 0.4,
			220 + blueVariation * 0.3,
			255,
			205
		);


		strokeWeight(2);


		point(
			p.pos.x,
			p.pos.y
		);
	}


	// ========================================================
	// SLOW ROTATION
	// ========================================================

	angle += 0.01;
}


// ============================================================
// ORIGINAL PARTICLE TARGET SYSTEM
// ============================================================

function updateTargets() {

	for (let p of points) {

		var i = p.index;


		let x =
			sin(i + angle) *
			sin(i * i) *
			radius_;


		let y =
			cos(i * i) *
			radius_;


		p.pos.set(
			x,
			y
		);
	}
}


// ============================================================
// AUDIO INITIALIZATION
// ============================================================

function startAudio() {

	// Don't create multiple AudioContexts
	if (audioStarted) {

		if (
			audioCtx &&
			audioCtx.state === "suspended"
		) {

			audioCtx.resume();
		}

		return;
	}


	const AudioContext =
		window.AudioContext ||
		window.webkitAudioContext;


	if (!AudioContext) {

		console.log(
			"Web Audio is not supported by this browser."
		);

		return;
	}


	audioCtx =
		new AudioContext();


	// --------------------------------------------------------
	// Master volume
	// --------------------------------------------------------

	masterGain =
		audioCtx.createGain();


	masterGain.gain.value =
		0.28;


	masterGain.connect(
		audioCtx.destination
	);


	audioStarted = true;


	// --------------------------------------------------------
	// Start cosmic pad
	// --------------------------------------------------------

	startCosmicPad();
}


// ============================================================
// COSMIC PAD
// ============================================================

function startCosmicPad() {

	let now =
		audioCtx.currentTime;


	// --------------------------------------------------------
	// Pad filter
	// --------------------------------------------------------

	padFilter =
		audioCtx.createBiquadFilter();


	padFilter.type =
		"lowpass";


	padFilter.frequency.value =
		650;


	padFilter.Q.value =
		0.4;


	padFilter.connect(
		masterGain
	);


	// --------------------------------------------------------
	// Pad envelope
	// --------------------------------------------------------

	padGain =
		audioCtx.createGain();


	padGain.gain.setValueAtTime(
		0,
		now
	);


	// Very slow attack
	padGain.gain.linearRampToValueAtTime(
		0.16,
		now + 8
	);


	padGain.connect(
		padFilter
	);


	// --------------------------------------------------------
	// Cosmic chord
	// --------------------------------------------------------

	createPadVoice(55.00);

	createPadVoice(82.41);

	createPadVoice(110.00);

	createPadVoice(164.81);
}


// ============================================================
// PAD VOICE
// ============================================================

function createPadVoice(freq) {

	let osc =
		audioCtx.createOscillator();


	let gain =
		audioCtx.createGain();


	// Soft waveform
	osc.type =
		"triangle";


	osc.frequency.value =
		freq;


	// Very subtle detuning
	osc.detune.value =
		random(-5, 5);


	gain.gain.value =
		0.16;


	osc.connect(gain);

	gain.connect(
		padGain
	);


	osc.start();


	// --------------------------------------------------------
	// Slow pitch movement
	// --------------------------------------------------------

	let lfo =
		audioCtx.createOscillator();


	let lfoGain =
		audioCtx.createGain();


	lfo.type =
		"sine";


	lfo.frequency.value =
		random(0.025, 0.06);


	lfoGain.gain.value =
		random(1.0, 2.5);


	lfo.connect(
		lfoGain
	);


	lfoGain.connect(
		osc.detune
	);


	lfo.start();
}


// ============================================================
// CRYSTAL SOUND
// Mouse moving across Mercury
// ============================================================

function playCrystal() {

	if (!audioCtx)
		return;


	var now =
		audioCtx.currentTime;


	// --------------------------------------------------------
	// Crystal oscillator
	// --------------------------------------------------------

	var osc =
		audioCtx.createOscillator();


	var gain =
		audioCtx.createGain();


	let filter =
		audioCtx.createBiquadFilter();


	osc.type =
		"triangle";


	// Bright, high frequency
	let crystalFreq =
		random(1100, 2600);


	osc.frequency.setValueAtTime(
		crystalFreq,
		now
	);


	// Tiny upward pitch movement
	osc.frequency.exponentialRampToValueAtTime(
		crystalFreq * random(1.08, 1.3),
		now + 0.12
	);


	// High-pass filter
	filter.type =
		"highpass";


	filter.frequency.value =
		800;


	// --------------------------------------------------------
	// Crystal envelope
	// --------------------------------------------------------

	gain.gain.setValueAtTime(
		0,
		now
	);


	gain.gain.linearRampToValueAtTime(
		0.055,
		now + 0.005
	);


	gain.gain.exponentialRampToValueAtTime(
		0.001,
		now + 0.38
	);


	osc.connect(filter);

	filter.connect(gain);

	gain.connect(
		masterGain
	);


	osc.start(now);

	osc.stop(
		now + 0.42
	);
}


// ============================================================
// PLUCK
// ============================================================

function playPluck() {

	if (!audioCtx)
		return;


	var now =
		audioCtx.currentTime;


	// --------------------------------------------------------
	// Main pluck
	// --------------------------------------------------------

	var osc =
		audioCtx.createOscillator();


	var gain =
		audioCtx.createGain();


	osc.type =
		"sine";


	let pluckFreq =
		random(180, 360);


	osc.frequency.setValueAtTime(
		pluckFreq,
		now
	);


	// Falling pitch
	osc.frequency.exponentialRampToValueAtTime(
		pluckFreq * 0.42,
		now + 0.45
	);


	// --------------------------------------------------------
	// Pluck envelope
	// --------------------------------------------------------

	gain.gain.setValueAtTime(
		0,
		now
	);


	gain.gain.linearRampToValueAtTime(
		0.20,
		now + 0.006
	);


	gain.gain.exponentialRampToValueAtTime(
		0.001,
		now + 0.65
	);


	osc.connect(gain);

	gain.connect(
		masterGain
	);


	osc.start(now);

	osc.stop(
		now + 0.7
	);


	// --------------------------------------------------------
	// Small high harmonic
	// --------------------------------------------------------

	let harmonic =
		audioCtx.createOscillator();


	let harmonicGain =
		audioCtx.createGain();


	harmonic.type =
		"triangle";


	harmonic.frequency.value =
		pluckFreq * 3.2;


	harmonicGain.gain.setValueAtTime(
		0.035,
		now
	);


	harmonicGain.gain.exponentialRampToValueAtTime(
		0.001,
		now + 0.25
	);


	harmonic.connect(
		harmonicGain
	);


	harmonicGain.connect(
		masterGain
	);


	harmonic.start(now);

	harmonic.stop(
		now + 0.3
	);
}


// ============================================================
// MOUSE MOVEMENT
// ============================================================

function mouseMoved() {

	// --------------------------------------------------------
	// Audio must be started by user interaction
	// --------------------------------------------------------

	if (!audioStarted) {
		return;
	}


	// --------------------------------------------------------
	// Position relative to Mercury
	// --------------------------------------------------------

	let mouseXRelative =
		(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2;


	let mouseYRelative =
		(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2;


	let mouseRadius =
		sqrt(
			mouseXRelative *
			mouseXRelative +

			mouseYRelative *
			mouseYRelative
		);


	// --------------------------------------------------------
	// Only make sound when mouse is touching Mercury
	// --------------------------------------------------------

	if (
		mouseRadius <
		radius_ + repel_radius
	) {

		var now =
			millis();


		// Prevent too many crystal sounds
		if (
			now -
			lastCrystalTime >
			140
		) {

			playCrystal();

			lastCrystalTime =
				now;
		}
	}
}


// ============================================================
// MOUSE CLICK
// ============================================================

function mousePressed() {

	// --------------------------------------------------------
	// First click starts the audio system
	// --------------------------------------------------------

	if (!audioStarted) {

		startAudio();
	}


	// --------------------------------------------------------
	// Position relative to Mercury
	// --------------------------------------------------------

	let clickX =
		(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2;


	let clickY =
		(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2;


	let clickRadius =
		sqrt(
			clickX * clickX +
			clickY * clickY
		);


	// --------------------------------------------------------
	// Click Mercury
	// --------------------------------------------------------

	if (
		clickRadius <
		radius_
	) {

		// Pluck sound
		playPluck();


		// ----------------------------------------------------
		// Local particle impulse
		// ----------------------------------------------------

		for (let p of points) {

			let dx =
				p.pos.x -
				clickX;


			let dy =
				p.pos.y -
				clickY;


			let particleDistance =
				sqrt(
					dx * dx +
					dy * dy
				);


			if (
				particleDistance > 0 &&
				particleDistance < 70
			) {

				let force =
					1 -
					particleDistance /
					70;


				p.vel.x +=
					(dx / particleDistance) *
					force *
					10;


				p.vel.y +=
					(dy / particleDistance) *
					force *
					10;
			}
		}
	}
}

